"use client";

import {
  Headphones,
  LoaderCircle,
  Mic,
  MicOff,
  Pause,
  Phone,
  PhoneIncoming,
  PhoneOff,
  Play,
  RotateCcw,
  ShieldAlert,
  Signal,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";

export type SoftphoneState =
  | "idle"
  | "ringing"
  | "active"
  | "held"
  | "recovering"
  | "permission-denied"
  | "error";

export type SoftphoneLabels = {
  idle: string;
  ringing: string;
  active: string;
  held: string;
  recovering: string;
  permissionDenied: string;
  error: string;
  accept: string;
  decline: string;
  hangup: string;
  mute: string;
  unmute: string;
  hold: string;
  resume: string;
  reconnect: string;
  testDevice: string;
  idleDescription: string;
  ringingDescription: string;
  activeDescription: string;
  recoveringDescription: string;
  permissionDescription: string;
  errorDescription: string;
};

const defaultLabels: SoftphoneLabels = {
  idle: "Your call workspace",
  ringing: "Incoming call",
  active: "In a call",
  held: "On hold",
  recovering: "Reconnecting",
  permissionDenied: "Microphone permission denied",
  error: "Connection unavailable",
  accept: "Answer",
  decline: "Decline",
  hangup: "End call",
  mute: "Mute",
  unmute: "Unmute",
  hold: "Hold",
  resume: "Resume",
  reconnect: "Reconnect",
  testDevice: "Test device",
  idleDescription:
    "Connect your session to receive calls from the support queue.",
  ringingDescription: "A caller is waiting. Answer when you are ready.",
  activeDescription:
    "Mute and call status are separate from the connection state.",
  recoveringDescription:
    "Signaling was interrupted. The remote call remains open until the backend confirms its end.",
  permissionDescription:
    "Allow microphone access in your browser, then test the device again.",
  errorDescription:
    "Review the connection and reconnect when the service is available.",
};

export function formatCallDuration(seconds: number) {
  const total = Number.isFinite(seconds) ? Math.max(0, Math.floor(seconds)) : 0;
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const remainder = total % 60;
  return [
    hours || undefined,
    hours ? minutes : Math.floor(total / 60),
    remainder,
  ]
    .filter((part) => part !== undefined)
    .map((part) => String(part).padStart(2, "0"))
    .join(":");
}

export type SoftphoneProps = {
  state?: SoftphoneState;
  contact?: string;
  metadata?: string;
  seconds?: number;
  muted?: boolean;
  /** An answer was requested; the adapter has not confirmed the call yet. */
  pending?: boolean;
  busy?: boolean;
  holdAvailable?: boolean;
  disabled?: boolean;
  labels?: Partial<SoftphoneLabels>;
  onAccept?: () => void;
  onDecline?: () => void;
  onHangup?: () => void;
  onMute?: () => void;
  onHold?: () => void;
  onReconnect?: () => void;
  onTestDevice?: () => void;
  className?: string;
};

/** Controlled call surface. Runtime and provider credentials belong to an adapter. */
export function Softphone({
  state = "idle",
  contact,
  metadata,
  seconds = 0,
  muted = false,
  pending = false,
  busy = false,
  holdAvailable = false,
  disabled = false,
  labels: overrides,
  onAccept,
  onDecline,
  onHangup,
  onMute,
  onHold,
  onReconnect,
  onTestDevice,
  className,
}: SoftphoneProps) {
  const labels = { ...defaultLabels, ...overrides };
  const active = state === "active" || state === "held";
  const recovering = state === "recovering";
  const denied = state === "permission-denied";
  const failed = state === "error";
  const ringing = state === "ringing";
  const status = denied
    ? labels.permissionDenied
    : recovering
      ? labels.recovering
      : labels[
          state as Exclude<SoftphoneState, "permission-denied" | "recovering">
        ];
  const description = denied
    ? labels.permissionDescription
    : failed
      ? labels.errorDescription
      : recovering
        ? labels.recoveringDescription
        : ringing
          ? labels.ringingDescription
          : active
            ? labels.activeDescription
            : labels.idleDescription;
  const StatusIcon =
    denied || failed
      ? ShieldAlert
      : ringing
        ? PhoneIncoming
        : active
          ? Phone
          : Headphones;

  return (
    <Card
      className={cn(
        "relative grid content-start gap-4 overflow-hidden p-6",
        ringing && "border-primary/50",
        (denied || failed) && "border-destructive/45",
        className,
      )}
      data-testid="softphone-call-panel"
      data-softphone-state={state}
      aria-label={labels.idle}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 h-px bg-[image:var(--af-gradient-primary)]"
      />
      <div className="flex flex-wrap items-center justify-between gap-3">
        <Badge
          variant={
            denied || failed
              ? "destructive"
              : active || ringing
                ? "default"
                : "neutral"
          }
          data-testid="softphone-call-status"
          role="status"
          aria-live="polite"
        >
          {recovering ? (
            <LoaderCircle
              aria-hidden="true"
              className="motion-safe:animate-spin"
            />
          ) : (
            <span
              aria-hidden="true"
              className={cn(
                "size-1.5 rounded-full bg-current",
                ringing && "motion-safe:animate-pulse",
              )}
            />
          )}
          {status}
        </Badge>
        <Signal aria-hidden="true" className="size-4 text-muted-foreground" />
      </div>
      <div className="pt-3">
        <span
          aria-hidden="true"
          className={cn(
            "mb-5 flex size-12 items-center justify-center rounded-2xl border border-primary/20 bg-accent text-primary",
            active &&
              "bg-[image:var(--af-gradient-primary)] text-primary-foreground",
          )}
        >
          <StatusIcon className="size-5" />
        </span>
        <h2 className="break-words text-2xl leading-9 font-semibold tracking-tight">
          {contact || labels.idle}
        </h2>
        {metadata && (
          <p className="mt-1 break-words text-[13px] leading-6 text-muted-foreground">
            {metadata}
          </p>
        )}
        {active && (
          <p
            className="mt-4 text-[32px] leading-10 font-medium tracking-tight tabular-nums"
            data-testid="softphone-duration"
            aria-label={formatCallDuration(seconds)}
          >
            {formatCallDuration(seconds)}
          </p>
        )}
      </div>

      {ringing && pending ? (
        <Button
          className="min-h-11"
          variant="destructive"
          data-testid="softphone-hangup"
          onClick={onHangup}
          loading={busy}
          disabled={disabled || !onHangup}
        >
          <PhoneOff aria-hidden="true" />
          {labels.hangup}
        </Button>
      ) : ringing ? (
        <div className="grid grid-cols-1 gap-2 min-[400px]:grid-cols-2">
          <Button
            className="min-h-11"
            appearance="gradient"
            data-testid="softphone-accept"
            onClick={onAccept}
            loading={busy}
            disabled={disabled || !onAccept}
          >
            <Phone aria-hidden="true" />
            {labels.accept}
          </Button>
          <Button
            className="min-h-11"
            variant="outline"
            data-testid="softphone-decline"
            onClick={onDecline}
            disabled={busy || disabled || !onDecline}
          >
            <PhoneOff aria-hidden="true" />
            {labels.decline}
          </Button>
        </div>
      ) : active ? (
        <>
          <div className="grid grid-cols-2 gap-2">
            <Button
              className="min-h-11"
              variant="outline"
              data-testid="softphone-mute"
              aria-pressed={muted}
              onClick={onMute}
              disabled={busy || disabled || !onMute}
            >
              {muted ? (
                <MicOff aria-hidden="true" />
              ) : (
                <Mic aria-hidden="true" />
              )}
              {muted ? labels.unmute : labels.mute}
            </Button>
            <Button
              className="min-h-11"
              variant="outline"
              data-testid="softphone-hold"
              aria-pressed={state === "held"}
              onClick={onHold}
              disabled={busy || disabled || !onHold || !holdAvailable}
            >
              {state === "held" ? (
                <Play aria-hidden="true" />
              ) : (
                <Pause aria-hidden="true" />
              )}
              {state === "held" ? labels.resume : labels.hold}
            </Button>
          </div>
          <Button
            className="min-h-11"
            variant="destructive"
            data-testid="softphone-hangup"
            onClick={onHangup}
            loading={busy}
            disabled={disabled || !onHangup}
          >
            <PhoneOff aria-hidden="true" />
            {labels.hangup}
          </Button>
        </>
      ) : recovering || failed ? (
        <Button
          className="min-h-11 w-fit"
          variant="outline"
          data-testid="softphone-reconnect"
          onClick={onReconnect}
          loading={busy}
          disabled={disabled || !onReconnect}
        >
          <RotateCcw aria-hidden="true" />
          {labels.reconnect}
        </Button>
      ) : (
        <Button
          className="min-h-11 w-fit"
          variant="outline"
          data-testid="softphone-test-device"
          onClick={onTestDevice}
          disabled={busy || !onTestDevice}
        >
          <Headphones aria-hidden="true" />
          {labels.testDevice}
        </Button>
      )}
      {recovering && onHangup && (
        <Button
          className="min-h-11 w-fit"
          variant="destructive"
          data-testid="softphone-hangup"
          onClick={onHangup}
          loading={busy}
          disabled={disabled}
        >
          <PhoneOff aria-hidden="true" />
          {labels.hangup}
        </Button>
      )}
      <p className="text-[13px] leading-6 text-muted-foreground">
        {description}
      </p>
    </Card>
  );
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
export const badgeVariants = cva(
  "af-badge inline-flex max-w-full items-center gap-1.5 whitespace-nowrap rounded-full border border-transparent px-2.5 py-1 text-[11px] leading-4 font-semibold tracking-[.01em] [&_svg]:size-3 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-accent text-accent-foreground",
        neutral: "bg-surface-subtle text-muted-foreground",
        warning: "bg-warning text-warning-foreground",
        destructive: "bg-destructive text-destructive-foreground",
        outline: "border-border bg-transparent text-foreground",
      },
    },
    defaultVariants: { variant: "default" },
  },
);
export type BadgeAppearance =
  "solid" | "soft" | "outline" | "glass" | "gradient";
const appearanceClasses: Record<BadgeAppearance, string> = {
  solid: "bg-primary text-primary-foreground",
  soft: "bg-accent text-accent-foreground",
  outline: "border-border bg-transparent text-foreground",
  glass: "border-border bg-[var(--af-glass-background)] text-foreground",
  gradient:
    "bg-primary text-primary-foreground [background-image:var(--af-gradient-primary)]",
};
export type BadgeProps = React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    appearance?: BadgeAppearance;
  };
export function Badge({
  className,
  variant,
  appearance,
  ...props
}: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-variant={variant ?? "default"}
      data-appearance={appearance}
      className={cn(
        badgeVariants({ variant }),
        appearance && `af-badge-${appearance}`,
        appearance && appearanceClasses[appearance],
        appearance &&
          variant === "warning" &&
          "bg-warning text-warning-foreground [background-image:none]",
        appearance &&
          variant === "destructive" &&
          "bg-destructive text-destructive-foreground [background-image:none]",
        className,
      )}
      {...props}
    />
  );
}

"use client";
import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { LoaderCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import "@/styles/effects.css";

export const buttonVariants = cva(
  "af-button af-control inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap border border-transparent text-[13px] leading-5 font-semibold tracking-[-.01em] outline-none transition-[background-color,border-color,color,box-shadow,transform] duration-[var(--af-motion-fast,150ms)] active:scale-[.98] motion-reduce:transform-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-45 data-disabled:pointer-events-none data-disabled:opacity-45 [@media(pointer:coarse)]:min-h-11 [@media(pointer:coarse)]:min-w-11 [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
          "af-button-primary bg-primary text-primary-foreground hover:bg-[color:var(--af-shade-primary,var(--primary-hover))]",
        outline:
          "af-button-outline border-border bg-surface text-foreground [background-image:none] hover:border-primary/40 hover:bg-[color:var(--af-shade-outline,var(--surface-subtle))]",
        secondary:
          "af-button-surface bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface,var(--accent))] hover:text-foreground",
        ghost:
          "bg-transparent text-muted-foreground hover:bg-surface-subtle hover:text-foreground",
        destructive:
          "af-button-destructive bg-destructive text-destructive-foreground [background-image:none] hover:bg-[color:var(--af-shade-destructive,var(--destructive))]",
        link: "af-hover-link bg-transparent text-primary underline underline-offset-4 hover:text-primary-hover",
      },
      size: {
        sm: "h-8 px-3",
        default: "h-[var(--af-control-height,40px)] px-4",
        lg: "h-12 px-6 text-sm",
        icon: "size-[var(--af-control-height,40px)]",
        "icon-sm": "size-8",
      },
      shape: {
        rounded: "rounded-[var(--radius-md,10px)]",
        pill: "rounded-full",
        square: "rounded-none",
      },
    },
    defaultVariants: { variant: "default", size: "default", shape: "rounded" },
  },
);
export type ButtonShape = "rounded" | "pill" | "square";
export type ButtonAppearance =
  "solid" | "soft" | "outline" | "glass" | "gradient";
const appearanceClasses: Record<ButtonAppearance, string> = {
  solid: "[background-image:none]",
  soft: "border-primary/25 bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface)] hover:text-foreground",
  outline:
    "border-primary/40 bg-surface text-foreground [background-image:none] hover:bg-[color:var(--af-shade-outline)] hover:text-foreground",
  glass:
    "border-primary/30 bg-[var(--af-glass-background)] text-foreground hover:bg-[var(--af-glass-background)] hover:text-foreground",
  gradient:
    "border-transparent bg-primary text-primary-foreground [background-image:var(--af-gradient-primary)] hover:bg-primary-hover hover:text-primary-foreground",
};
export type ButtonProps = Omit<
  React.ComponentProps<typeof ButtonPrimitive>,
  "className"
> &
  VariantProps<typeof buttonVariants> & {
    className?: string;
    loading?: boolean;
    appearance?: ButtonAppearance;
  };
export function Button({
  className,
  variant,
  size,
  shape,
  loading,
  appearance,
  children,
  disabled,
  focusableWhenDisabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-busy": ariaBusy,
  ...props
}: ButtonProps) {
  const labelId = React.useId();
  return (
    <ButtonPrimitive
      {...props}
      data-slot="button"
      data-variant={variant ?? "default"}
      data-size={size ?? "default"}
      data-shape={shape ?? "rounded"}
      data-appearance={appearance}
      className={cn(
        buttonVariants({ variant, size, shape }),
        appearance && `af-control-${appearance}`,
        appearance &&
          variant !== "destructive" &&
          appearanceClasses[appearance],
        className,
      )}
      disabled={disabled || loading}
      focusableWhenDisabled={focusableWhenDisabled ?? loading}
      aria-busy={loading || ariaBusy}
      aria-label={ariaLabel}
      aria-labelledby={
        ariaLabelledBy ?? (loading && !ariaLabel ? labelId : undefined)
      }
    >
      {loading && (
        <LoaderCircle
          className="motion-safe:animate-spin motion-reduce:animate-none [[data-motion-level=off]_&]:animate-none"
          aria-hidden="true"
        />
      )}
      <span id={labelId} className="contents">
        {children}
      </span>
    </ButtonPrimitive>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import "@/styles/effects.css";
export type CardAppearance = "flat" | "elevated" | "glass" | "gradient";
export type CardProps = React.ComponentProps<"div"> & {
  appearance?: CardAppearance;
};
export function Card({ className, appearance, ...props }: CardProps) {
  return (
    <div
      data-slot="card"
      data-appearance={appearance}
      className={cn(
        "af-card af-shadow-soft min-w-0 rounded-[var(--af-radius,16px)] border border-border text-foreground",
        appearance && `af-card-${appearance}`,
        className,
      )}
      {...props}
    />
  );
}
export function CardHeader({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        "flex min-w-0 flex-col gap-2 p-[var(--af-card-padding,24px)]",
        className,
      )}
      {...props}
    />
