}
export function CardContent({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-content"
      className={cn(
        "min-w-0 px-[var(--af-card-padding,24px)] pb-[var(--af-card-padding,24px)]",
        className,
      )}
      {...props}
    />
