}
export function CardFooter({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-footer"
      className={cn(
        "flex flex-wrap items-center gap-3 px-[var(--af-card-padding,24px)] pb-[var(--af-card-padding,24px)]",
        className,
      )}
      {...props}
    />
